-- ════════════════════════════════════════════════════════════════════════

insert into public.courses
  (id, title, description, ai_instructions, icon, color, category, subcategory, difficulty, locked, modules)
values
  ('course-consola-basica', 'Consola de Comandos: Primeros Pasos', 'La introducción más sencilla posible a la terminal: qué es, cómo se abre y los comandos básicos para moverte sin miedo. Pensado para quien nunca ha escrito un comando en su vida.', 'Eres el Mago, tutor de "Consola de Comandos: Primeros Pasos" en Oliver Academy. Explica cada comando con calma y ejemplos concretos, recuerda al estudiante que equivocarse en la consola casi nunca rompe nada, y nunca uses jerga sin explicarla primero. Sé paciente con quien nunca haya usado una terminal. Sé breve.', '⌨️', '#38bdf8', 'Programación', 'Terminal y Sistemas', 'principiante', false, '[{"id":"cons-01","order":1,"type":"text","title":"¿Qué es la consola y para qué sirve?","description":"La otra forma de hablarle a tu computadora: con palabras en vez de clics.","content":"<h2>Dos formas de hablarle a una computadora</h2><p>Normalmente usas una computadora haciendo <strong>clic</strong> en iconos y botones — eso se llama interfaz gráfica. La <strong>consola</strong> (también llamada terminal, línea de comandos, o \"cmd\") es la otra forma: en vez de hacer clic, <strong>escribes</strong> lo que quieres que la computadora haga, palabra por palabra.</p><div class=\"tip\">💡 No es una computadora distinta ni algo \"de hackers\" — es la MISMA computadora, solo que le hablas de otra manera. Todo lo que ves en pantallas e iconos, por dentro, se traduce a comandos como estos.</div><h2>¿Por qué alguien preferiría escribir en vez de hacer clic?</h2><ul><li><strong>Es más rápido</strong> una vez que sabes los comandos — no hay que buscar el botón correcto entre menús.</li><li><strong>Se puede repetir</strong> exactamente igual mil veces, sin volver a hacer los mismos clics.</li><li>Es la única forma de controlar muchas computadoras que <strong>no tienen pantalla</strong> — como los servidores que hacen funcionar internet.</li></ul><div class=\"example\">🧪 Es como la diferencia entre pedir comida señalando fotos en un menú (interfaz gráfica) y decirle al mesero exactamente lo que quieres en voz alta (consola). Ambas formas piden la misma comida.</div><h2>Lo más importante antes de empezar</h2><div class=\"warn\">⚠️ En este curso vas a escribir SOLO comandos seguros para aprender. Nada de lo que hagamos aquí puede romper tu computadora — el objetivo es que pierdas el miedo, no que te arriesgues.</div>","exercises":[{"id":"cons-01-1","type":"challenge","prompt":"Piensa en una tarea que hagas seguido con clics (abrir una carpeta, buscar un archivo). ¿Cómo crees que se vería pedirle lo mismo a la computadora con palabras escritas? Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Cuál es la diferencia principal entre la interfaz gráfica y la consola?","options":["Son dos computadoras distintas","Una usa clics, la otra usa comandos escritos, pero es la misma computadora","La consola es solo para internet","La interfaz gráfica ya no se usa"],"correctIndex":1},"comments":[]},{"id":"cons-02","order":2,"type":"text","title":"Abre tu consola por primera vez","description":"Encuéntrala en tu sistema y escribe tu primer comando.","content":"<h2>Cómo abrir la consola según tu sistema</h2><ul><li><strong>Windows:</strong> presiona la tecla de Windows, escribe <code>cmd</code> o <code>PowerShell</code>, y presiona Enter sobre el resultado.</li><li><strong>Mac:</strong> abre Spotlight (Cmd + Espacio), escribe <code>Terminal</code> y presiona Enter.</li><li><strong>Linux:</strong> normalmente Ctrl + Alt + T abre una terminal directamente.</li></ul><p>Va a aparecer una ventana con fondo oscuro (o claro) y texto — y un cursor parpadeando esperando a que escribas algo. Eso es todo, ya estás dentro.</p><div class=\"tip\">💡 Esa ventana no hace nada por sí sola hasta que tú escribes algo y presionas Enter. No hay forma de \"activar sin querer\" nada solo con tenerla abierta.</div><h2>Tu primer comando: saluda a la consola</h2><p>Escribe exactamente esto y presiona Enter:</p><pre><code>echo Hola Mundo</code></pre><p>La consola te va a devolver el mismo texto: <code>Hola Mundo</code>. Acabas de darle una instrucción a la computadora y ella la ejecutó — <strong>eso es programar</strong>, en su forma más simple.</p><div class=\"example\">🧪 <code>echo</code> es un comando que simplemente repite lo que le escribes después. Es el \"hola mundo\" clásico con el que casi todo el mundo empieza a aprender consola.</div>","exercises":[{"id":"cons-02-1","type":"challenge","prompt":"Abre tu consola y escribe \"echo\" seguido de tu propio nombre. ¿Qué pasó? Cuéntaselo a tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué hace el comando \"echo Hola Mundo\"?","options":["Borra la pantalla","Repite el texto \"Hola Mundo\" en la consola","Abre un navegador","Apaga la computadora"],"correctIndex":1},"comments":[]},{"id":"cons-03","order":3,"type":"text","title":"El cursor parpadeante: cómo escribir comandos","description":"La estructura básica de cualquier comando, y atajos que te van a salvar.","content":"<h2>La forma de un comando</h2><p>Casi todo comando sigue la misma estructura:</p><pre><code>comando [opciones] [algo sobre lo que actuar]</code></pre><p>Por ejemplo, en <code>echo Hola Mundo</code>: <code>echo</code> es el comando, y <code>Hola Mundo</code> es el texto sobre el que actúa.</p><div class=\"warn\">⚠️ La consola distingue entre mayúsculas y minúsculas en Mac y Linux (no tanto en Windows) — <code>Echo</code> no siempre es lo mismo que <code>echo</code>. Si un comando \"no funciona\", revisa primero que lo escribiste exactamente igual.</div><h2>Tres atajos que vas a usar todo el tiempo</h2><ul><li><strong>Flecha hacia arriba (↑):</strong> repite el último comando que escribiste, sin tener que volver a teclearlo entero.</li><li><strong>Tab:</strong> autocompleta el nombre de un archivo o carpeta mientras escribes — ahorra errores de dedo.</li><li><strong>Ctrl + C:</strong> cancela lo que se esté ejecutando si algo se queda \"trabado\" o tarda demasiado.</li></ul><div class=\"tip\">💡 Ctrl + C es tu botón de pánico seguro — nunca rompe nada, solo detiene lo que estaba corriendo. Úsalo sin miedo cuando algo no se ve bien.</div>","exercises":[{"id":"cons-03-1","type":"challenge","prompt":"Escribe cualquier comando, presiona Enter, y luego presiona la flecha hacia arriba (↑). ¿Qué pasó en la línea de comandos?","solution":""}],"resources":[],"quiz":null,"comments":[]},{"id":"cons-04","order":4,"type":"text","title":"Moverte por las carpetas: pwd, cd, ls/dir","description":"Cómo saber dónde estás y moverte entre carpetas sin usar el mouse.","content":"<h2>¿Dónde estoy? — pwd</h2><p>La consola siempre \"está parada\" dentro de una carpeta, aunque no lo veas. Para saber en cuál, escribe (en Mac/Linux):</p><pre><code>pwd</code></pre><p>Te va a mostrar la ruta completa de dónde estás — como una dirección postal, pero de carpetas.</p><h2>¿Qué hay aquí? — ls / dir</h2><ul><li><strong>Mac/Linux:</strong> <code>ls</code> muestra los archivos y carpetas del lugar donde estás.</li><li><strong>Windows:</strong> <code>dir</code> hace lo mismo.</li></ul><h2>Moverme a otra carpeta — cd</h2><p><code>cd</code> significa \"change directory\" (cambiar de carpeta). Se usa así:</p><pre><code>cd Documentos</code></pre><p>Eso te mueve DENTRO de la carpeta Documentos. Para regresar un nivel hacia atrás:</p><pre><code>cd ..</code></pre><div class=\"example\">🧪 Es exactamente lo mismo que hacer doble clic para entrar a una carpeta y luego dar clic en \"atrás\" — solo que ahora lo escribes en vez de hacer clic.</div><div class=\"tip\">💡 Usa Tab mientras escribes el nombre de una carpeta después de <code>cd</code> — la consola la autocompleta por ti, así no importa si no recuerdas el nombre exacto.</div>","exercises":[{"id":"cons-04-1","type":"challenge","prompt":"Usa \"cd\" para entrar a alguna carpeta que tengas (Documentos, Escritorio/Desktop), luego usa \"ls\" o \"dir\" para ver qué hay adentro. ¿Coincide con lo que ves normalmente con el mouse?","solution":""}],"resources":[],"quiz":{"question":"¿Para qué sirve el comando \"cd\"?","options":["Para borrar carpetas","Para moverte entre carpetas","Para crear archivos","Para apagar la consola"],"correctIndex":1},"comments":[]},{"id":"cons-05","order":5,"type":"text","title":"Archivos y carpetas: crear, ver y (con cuidado) borrar","description":"Los comandos básicos para trabajar con archivos, y la única regla de seguridad que de verdad importa.","content":"<h2>Crear una carpeta</h2><pre><code>mkdir practica</code></pre><p>Esto crea una nueva carpeta llamada \"practica\" donde estés parado.</p><h2>Crear un archivo vacío</h2><ul><li><strong>Mac/Linux:</strong> <code>touch nota.txt</code></li><li><strong>Windows:</strong> <code>type nul > nota.txt</code></li></ul><h2>Ver el contenido de un archivo</h2><ul><li><strong>Mac/Linux:</strong> <code>cat nota.txt</code></li><li><strong>Windows:</strong> <code>type nota.txt</code></li></ul><h2>Borrar — con mucho cuidado</h2><p>Para borrar un archivo: <code>rm nota.txt</code> (Mac/Linux) o <code>del nota.txt</code> (Windows).</p><div class=\"warn\">⚠️ Esta es la regla más importante de todo el curso: cuando borras algo desde la consola, <strong>NO va a la papelera de reciclaje</strong>. Se borra directo, sin posibilidad de recuperarlo fácilmente. Antes de borrar algo, revisa dos veces el nombre con \"ls\"/\"dir\".</div><div class=\"tip\">💡 Para practicar sin miedo, siempre crea primero una carpeta nueva (como \"practica\" arriba) y haz todos tus experimentos ahí adentro — así, aunque algo salga mal, solo afecta esa carpeta de prueba.</div>","exercises":[{"id":"cons-05-1","type":"challenge","prompt":"Crea una carpeta de práctica, entra a ella con \"cd\", crea un archivo de texto adentro, y luego bórralo. Cuéntale a tu mascota los comandos que usaste en orden.","solution":""}],"resources":[],"quiz":{"question":"¿Qué pasa cuando borras un archivo desde la consola con \"rm\" o \"del\"?","options":["Se mueve a la papelera de reciclaje","Se borra directo, sin papelera","Solo se oculta","Pide confirmación siempre"],"correctIndex":1},"comments":[]},{"id":"cons-06","order":6,"type":"text","title":"Los errores no dan miedo","description":"Cómo leer un mensaje de error sin entrar en pánico.","content":"<h2>Vas a ver errores — es normal</h2><p>Todo el mundo que usa la consola, sin excepción, ve mensajes de error todo el tiempo. No significa que rompiste algo — casi siempre significa una de estas dos cosas:</p><ul><li><strong>Un error de dedo:</strong> escribiste el comando o el nombre del archivo un poco distinto.</li><li><strong>Estás en la carpeta equivocada:</strong> el archivo que buscas no está donde tú estás parado.</li></ul><div class=\"example\">🧪 Un mensaje como \"command not found\" o \"no se reconoce como un comando\" casi siempre es un error de dedo. Revisa mayúsculas, espacios y que el comando exista en tu sistema.</div><h2>Cómo investigar sin pánico</h2><ol><li>Usa <code>ls</code> o <code>dir</code> para confirmar que estás donde crees que estás.</li><li>Revisa el comando letra por letra.</li><li>Si sigues atorado, copia el mensaje de error y pregúntale a tu mascota IA — describe exactamente qué escribiste.</li></ol><div class=\"tip\">💡 Un mensaje de error no es un castigo, es información. La consola te está diciendo exactamente qué no entendió — leerlo con calma casi siempre resuelve el problema en segundos.</div>","exercises":[{"id":"cons-06-1","type":"challenge","prompt":"Escribe a propósito un comando mal escrito (por ejemplo \"lsx\" en vez de \"ls\") y observa el mensaje de error. ¿Qué te dice?","solution":""}],"resources":[],"quiz":null,"comments":[]},{"id":"cons-07","order":7,"type":"text","title":"¿Y ahora qué? Tu siguiente paso","description":"Un repaso de todo lo que ya sabes, y hacia dónde seguir.","content":"<h2>Lo que ya sabes hacer</h2><ul><li>Abrir la consola en tu sistema.</li><li>Escribir un comando y entender su estructura básica.</li><li>Moverte entre carpetas con <code>cd</code>, <code>pwd</code>, <code>ls</code>/<code>dir</code>.</li><li>Crear, ver y borrar archivos con cuidado.</li><li>Leer un error sin asustarte.</li></ul><div class=\"tip\">💡 Con esto ya puedes hacer más de lo que crees: navegar cualquier sistema Linux/Mac sin mouse, entender instrucciones técnicas que digan \"abre tu terminal y ejecuta...\", y perder el miedo a esa ventana negra que antes se veía intimidante.</div><h2>¿Hacia dónde seguir?</h2><p>Este curso fue el primer paso, a propósito muy pequeño y sin prisa. Cuando te sientas listo para ir más a fondo — pipes, permisos, scripts que automatizan tareas completas, y una terminal interactiva para practicar en cada lección — el curso <strong>\"Bash desde Cero\"</strong> de esta misma Academia continúa exactamente desde aquí.</p><div class=\"example\">🧪 No hay ninguna prisa. Practica estos comandos unos días hasta que se sientan naturales antes de seguir — la consola se aprende con las manos, no solo leyendo.</div>","exercises":[],"resources":[],"quiz":null,"comments":[]}]'::jsonb),
  ('course-aprender-a-aprender', 'Aprende a Aprender: Domina Temas Difíciles', 'Técnicas simples y reales (no magia) para entender cosas complicadas más rápido: dividir en partes, la técnica Feynman, repetición espaciada y práctica activa. Para cualquier tema, no solo estudios.', 'Eres el Perro Globo, tutor de "Aprende a Aprender" en Oliver Academy. Anima al estudiante con energía positiva, da ejemplos concretos de las técnicas (Feynman, repetición espaciada, práctica activa) y recuérdale que aprender es una habilidad que se entrena, no un talento fijo. Sé breve.', '🧭', '#34d399', 'Productividad', 'Aprendizaje', 'principiante', false, '[{"id":"apr-01","order":1,"type":"text","title":"No es que \"no sirvas para esto\"","description":"Por qué \"no tengo la mente para esto\" casi siempre es un mito, no un hecho.","content":"<h2>La idea que hay que soltar primero</h2><p>Mucha gente cree que aprender cosas difíciles depende de un talento con el que naces — \"soy malo para las matemáticas\", \"no tengo cabeza para la tecnología\". La investigación sobre aprendizaje dice otra cosa: <strong>entender temas difíciles es una habilidad que se entrena</strong>, como un músculo, no un rasgo fijo con el que naces o no.</p><div class=\"tip\">💡 Esto tiene nombre: se llama \"mentalidad de crecimiento\" — la idea de que la capacidad mejora con esfuerzo y estrategia correcta, no que está fija desde el nacimiento.</div><h2>¿Por qué se siente tan difícil entonces?</h2><p>Casi siempre no es falta de capacidad — es falta de <strong>estrategia</strong>. Leer un texto complicado una sola vez, de corrido, y esperar entenderlo todo es como intentar levantar mucho peso sin nunca haber entrenado la técnica. El resto de este curso son las técnicas.</p><div class=\"example\">🧪 Nadie nace sabiendo andar en bicicleta — se cae, ajusta, lo vuelve a intentar. Entender un tema difícil funciona exactamente igual: no es cuestión de talento innato, es cuestión de repetición con la técnica correcta.</div>","exercises":[{"id":"apr-01-1","type":"challenge","prompt":"Piensa en algo que hoy haces bien pero que al principio se te dificultó mucho (leer, andar en bici, cocinar algo). ¿Qué cambió — talento nuevo, o práctica? Cuéntaselo a tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué dice este módulo sobre la capacidad de aprender cosas difíciles?","options":["Es un talento fijo, naces con él o no","Es una habilidad que se entrena con estrategia y práctica","Solo algunas personas pueden aprender temas técnicos","Depende únicamente de la edad"],"correctIndex":1},"comments":[]},{"id":"apr-02","order":2,"type":"text","title":"Divide y vencerás","description":"Por qué un tema \"imposible\" casi siempre es varios temas pequeños juntos.","content":"<h2>Lo grande abruma, lo pequeño no</h2><p>Cuando un tema se siente imposible, casi siempre es porque lo estás viendo completo, de un solo golpe. La técnica más simple y más poderosa para cualquier cosa difícil es: <strong>partirla en pedazos más chicos</strong>, y aprender un pedazo a la vez.</p><div class=\"example\">🧪 Nadie aprende a cocinar un banquete completo de una sola vez. Primero aprendes a hervir agua, luego a cortar verduras, luego una salsa simple — cada pedazo por separado se siente manejable, y el banquete completo termina siendo la suma de pedazos ya dominados.</div><h2>Cómo partir un tema difícil</h2><ol><li>Escribe el tema grande en una hoja.</li><li>Pregúntate: \"¿qué necesito entender ANTES de entender esto?\" — esas son las partes.</li><li>Ordénalas de lo más simple a lo más complejo.</li><li>Domina la primera parte antes de pasar a la siguiente.</li></ol><div class=\"tip\">💡 Si sigues sintiendo que un pedazo es \"demasiado grande\", divídelo otra vez. No hay un pedazo demasiado pequeño — solo pedazos que todavía no partiste lo suficiente.</div>","exercises":[{"id":"apr-02-1","type":"challenge","prompt":"Elige algo que te parezca difícil ahora mismo. Escribe 3 pedazos más pequeños en los que podrías dividirlo. Compártelos con tu mascota.","solution":""}],"resources":[],"quiz":null,"comments":[]},{"id":"apr-03","order":3,"type":"text","title":"La técnica Feynman: explícalo simple","description":"Si no lo puedes explicar fácil, todavía no lo entendiste del todo — y eso está bien.","content":"<h2>La prueba definitiva de que entendiste algo</h2><p>El físico Richard Feynman decía que la mejor forma de saber si de verdad entiendes algo es intentar <strong>explicárselo a alguien que no sabe nada del tema</strong>, usando solo palabras simples, sin jerga.</p><h2>Los 4 pasos de la técnica Feynman</h2><ol><li><strong>Elige el tema</strong> que quieres entender.</li><li><strong>Explícalo</strong> en voz alta o por escrito, como si se lo enseñaras a un niño de 10 años — sin palabras técnicas.</li><li><strong>Encuentra los huecos</strong> — los momentos donde te trabaste, usaste una palabra que en realidad no puedes explicar, o tuviste que \"inventar\" para seguir.</li><li><strong>Regresa a la fuente</strong> solo en esos huecos específicos, y vuelve a intentar la explicación simple.</li></ol><div class=\"example\">🧪 Si estás aprendiendo qué es \"internet\" y en tu explicación dices \"es una red de computadoras conectadas\" pero no puedes explicar qué significa \"conectadas\" en la práctica — ahí está tu hueco. Ve a resolver justo eso, no todo el tema de nuevo.</div><div class=\"tip\">💡 Trabarte al explicar no es fracaso — es exactamente el punto de este ejercicio: te muestra con precisión qué te falta, en vez de sentir vagamente que \"no entiendes nada\".</div>","exercises":[{"id":"apr-03-1","type":"challenge","prompt":"Elige algo que crees entender bien y explícaselo en voz alta a tu mascota (o a ti mismo) como si tuviera 10 años. ¿Dónde te trabaste?","solution":""}],"resources":[],"quiz":{"question":"¿Cuál es el objetivo real de intentar explicar un tema con palabras simples?","options":["Impresionar a otros con tu conocimiento","Encontrar exactamente qué partes no entiendes todavía","Memorizar el tema más rápido","Evitar tener que estudiar"],"correctIndex":1},"comments":[]},{"id":"apr-04","order":4,"type":"text","title":"Repasar la noche antes no funciona","description":"Por qué el cerebro olvida rápido, y cómo la repetición espaciada lo aprovecha a tu favor.","content":"<h2>El olvido es normal — y predecible</h2><p>Es normal olvidar la mayoría de lo que estudias en las primeras horas y días si no lo vuelves a repasar. Esto se llama \"curva del olvido\", y le pasa a todo el mundo — no es que tengas mala memoria.</p><div class=\"warn\">⚠️ Por eso \"empollar\" (estudiar todo de golpe la noche antes de un examen) casi nunca funciona a largo plazo: metes la información apretada por unas horas, pero se va casi tan rápido como llegó.</div><h2>La solución: repetición espaciada</h2><p>En vez de repasar todo una vez y ya, repasa el mismo tema varias veces, <strong>con días de por medio</strong> entre cada repaso. Cada vez que repasas justo antes de olvidarlo del todo, el cerebro lo refuerza y tarda más en volver a olvidarlo.</p><div class=\"example\">🧪 Un horario simple que funciona bien: repasa un tema nuevo al día siguiente, luego 3 días después, luego una semana después. Cada repaso es más corto que el anterior, pero el conocimiento se queda mucho más tiempo.</div><div class=\"tip\">💡 No necesitas una app complicada para esto — hasta unas notas con fecha en un calendario (\"repasar tema X el día Y\") ya aplican el principio.</div>","exercises":[{"id":"apr-04-1","type":"challenge","prompt":"Elige un tema que aprendiste hace poco. Anota en qué fechas lo repasarías si aplicaras la repetición espaciada (mañana, en 3 días, en una semana).","solution":""}],"resources":[],"quiz":{"question":"¿Por qué \"empollar\" la noche antes de un examen suele fallar a largo plazo?","options":["Porque el cerebro no puede procesar información de noche","Porque sin repasos espaciados en el tiempo, se olvida casi tan rápido como se aprendió","Porque los exámenes son injustos","Porque es imposible aprender rápido"],"correctIndex":1},"comments":[]},{"id":"apr-05","order":5,"type":"text","title":"Practicar de verdad vs. solo leer","description":"Por qué subrayar y releer se siente productivo pero enseña poco — y qué hacer en su lugar.","content":"<h2>La trampa de \"se ve conocido\"</h2><p>Releer un texto o subrayarlo se siente productivo porque, en la segunda o tercera lectura, todo \"se ve conocido\" — pero reconocer algo NO es lo mismo que poder recordarlo o usarlo sin tenerlo enfrente. Esa sensación de familiaridad engaña.</p><h2>Práctica activa: pon a prueba tu memoria, no solo tus ojos</h2><ul><li><strong>Autoevalúate:</strong> cierra el libro/apuntes e intenta escribir o decir lo que recuerdas, SIN ver la fuente.</li><li><strong>Hazte preguntas:</strong> en vez de releer, pregúntate \"¿qué pasaría si...?\" o \"¿por qué funciona así?\" y trata de responder antes de buscar la respuesta.</li><li><strong>Resuelve problemas reales</strong> del tema, no solo leas sobre cómo resolverlos.</li></ul><div class=\"example\">🧪 Es la diferencia entre ver a alguien más andar en bicicleta cien veces (releer) y subirte tú mismo, aunque te caigas al principio (práctica activa). Solo la segunda de verdad te enseña a andar en bici.</div><div class=\"tip\">💡 La práctica activa se siente más difícil e incómoda que releer — y esa incomodidad es justo la señal de que tu cerebro está trabajando de verdad, no solo reconociendo algo familiar.</div>","exercises":[{"id":"apr-05-1","type":"challenge","prompt":"La próxima vez que estudies algo, en vez de releerlo, cierra la fuente e intenta escribir de memoria lo que recuerdas. Compara qué tanto lograste recordar sin ver.","solution":""}],"resources":[],"quiz":null,"comments":[]},{"id":"apr-06","order":6,"type":"text","title":"Construye tu propio sistema","description":"Junta todo lo del curso en una lista simple que puedas usar con cualquier tema.","content":"<h2>Tu checklist para cualquier tema difícil</h2><ol><li><strong>Parte el tema</strong> en pedazos más pequeños y manejables.</li><li><strong>Aprende un pedazo</strong> a la vez, no todos juntos.</li><li><strong>Explícalo simple</strong> (técnica Feynman) para encontrar tus huecos reales.</li><li><strong>Repasa con espacio</strong> — mañana, en unos días, en una semana — en vez de todo de golpe.</li><li><strong>Practica de verdad</strong>: pon a prueba tu memoria sin ver la fuente, no solo releas.</li><li><strong>Sé paciente con los errores</strong> — equivocarte mientras practicas es parte del proceso, no una señal de que \"no sirves para esto\".</li></ol><div class=\"tip\">💡 Guarda esta lista. No importa si el tema es programación, un idioma nuevo, cocina o cualquier otra cosa — este mismo sistema aplica siempre.</div><h2>Un recordatorio final</h2><p>Nadie que hoy domina algo difícil empezó dominándolo. Empezó exactamente donde tú estás ahora: sin entender, con dudas, cometiendo errores — y usando algún sistema parecido a este, una y otra vez, hasta que dejó de sentirse difícil.</p><div class=\"example\">🧪 Este mismo curso es un ejemplo: si llegaste hasta aquí, ya aplicaste sin darte cuenta varias de estas técnicas — lo partiste en módulos pequeños, y avanzaste uno a la vez.</div>","exercises":[],"resources":[],"quiz":null,"comments":[]}]'::jsonb),
  ('course-informatica-basica', 'Primeros Pasos con la Computadora', 'El curso más básico posible: qué es cada parte de la computadora, cómo usar el mouse y el teclado, carpetas, internet y seguridad simple. Para quien casi no ha usado una computadora antes.', 'Eres Oliver, tutor cálido y muy paciente de "Primeros Pasos con la Computadora" en Oliver Academy — un curso para personas que casi no han usado una computadora. Explica todo sin tecnicismos, con analogías cotidianas, y nunca hagas sentir mal a quien pregunte algo "obvio". Sé breve.', '🌱', '#60a5fa', 'Alfabetización Digital', 'Fundamentos', 'principiante', false, '[{"id":"pc-01","order":1,"type":"text","title":"Las partes de una computadora, sin miedo","description":"Conoce cada pieza antes de tocarla — nada se rompe solo con verlo o tocarlo.","content":"<h2>Ninguna parte se rompe por tocarla</h2><p>Antes que nada: no hay ningún botón, tecla o parte de una computadora que se \"rompa\" solo por tocarla o hacer clic. Lo peor que puede pasar casi siempre es que algo se abra o se cierre — y eso siempre se puede deshacer.</p><h2>Las partes principales</h2><ul><li><strong>Pantalla / monitor:</strong> donde ves todo — imágenes, texto, botones.</li><li><strong>Teclado:</strong> para escribir letras, números y símbolos.</li><li><strong>Mouse (ratón) o touchpad:</strong> para mover una flechita en pantalla y seleccionar cosas.</li><li><strong>La torre / CPU:</strong> la caja donde está \"el cerebro\" de la computadora — en una laptop, todo esto está integrado en una sola pieza delgada.</li></ul><div class=\"tip\">💡 Una laptop (computadora portátil) tiene las cuatro partes juntas en un solo aparato que se dobla. Una computadora de escritorio las tiene separadas: pantalla, teclado, mouse y la torre, cada uno por su lado, conectados con cables.</div><div class=\"example\">🧪 Piensa en la computadora como una casa: la pantalla es la ventana por donde ves, el teclado y el mouse son las manos con las que interactúas, y la torre es donde \"vive\" todo lo que hace que funcione.</div>","exercises":[{"id":"pc-01-1","type":"challenge","prompt":"Mira tu computadora ahora mismo y señala (con el dedo o en voz alta) dónde está cada parte: pantalla, teclado, mouse/touchpad.","solution":""}],"resources":[],"quiz":{"question":"¿Qué pasa si tocas o haces clic en una parte de la computadora \"por error\"?","options":["Se rompe permanentemente","Nada grave — casi siempre se puede deshacer","Se borra todo el sistema","Debes reiniciar el aparato inmediatamente"],"correctIndex":1},"comments":[]},{"id":"pc-02","order":2,"type":"text","title":"Encender, apagar y el escritorio","description":"El primer contacto: prender la máquina y entender qué ves cuando enciende.","content":"<h2>Encender</h2><p>Busca un botón, casi siempre redondo, con un símbolo como un círculo con una línea vertical (⏻) — puede estar arriba del teclado o a un lado. Presiónalo una vez y espera; la computadora tarda entre unos segundos y un minuto en estar lista.</p><h2>El escritorio: tu mesa de trabajo virtual</h2><p>Cuando termina de encender, ves el <strong>escritorio</strong> — como una mesa de trabajo digital. Los pequeños dibujos que ves ahí son <strong>iconos</strong>: cada uno es un acceso directo a un programa o archivo. Doble clic sobre uno lo abre.</p><div class=\"tip\">💡 \"Doble clic\" significa presionar el botón izquierdo del mouse dos veces, rápido, seguidas — es la forma normal de abrir algo desde el escritorio.</div><h2>Apagar correctamente</h2><p>Nunca apagues jalando el cable o manteniendo presionado el botón — eso puede perder trabajo sin guardar. La forma correcta: busca el menú de inicio o el logo del sistema, y busca la opción \"Apagar\" (Shut down / Apagar equipo).</p><div class=\"warn\">⚠️ Guarda siempre lo que estés haciendo (documentos, trabajos) ANTES de apagar. Apagar sin guardar puede perder cambios que no habías guardado todavía.</div>","exercises":[{"id":"pc-02-1","type":"challenge","prompt":"Enciende tu computadora (si no lo has hecho ya) y encuentra 3 iconos en el escritorio. ¿Reconoces para qué sirve cada uno?","solution":""}],"resources":[],"quiz":null,"comments":[]},{"id":"pc-03","order":3,"type":"text","title":"El mouse y el teclado: tus dos manos digitales","description":"Los movimientos básicos que vas a usar en todo momento.","content":"<h2>El mouse (o touchpad)</h2><ul><li><strong>Clic izquierdo:</strong> selecciona o abre algo — el más usado, casi siempre con un solo toque.</li><li><strong>Clic derecho:</strong> abre un menú de opciones extra sobre lo que señalaste — \"click derecho para ver qué más puedo hacer aquí\" es una buena costumbre.</li><li><strong>Doble clic:</strong> abre programas o archivos desde iconos.</li><li><strong>Arrastrar:</strong> mantén presionado el clic izquierdo mientras mueves el mouse, para mover algo de un lugar a otro, y suéltalo donde quieras dejarlo.</li></ul><div class=\"tip\">💡 En una laptop, el touchpad hace lo mismo que un mouse: normalmente un dedo mueve el cursor, y hay dos zonas o botones abajo para clic izquierdo y derecho (o dos dedos = clic derecho, según la marca).</div><h2>El teclado: las teclas que más vas a usar</h2><ul><li><strong>Enter:</strong> confirma o \"acepta\" lo que escribiste, o crea un salto de línea.</li><li><strong>Espacio:</strong> deja un espacio en blanco entre palabras.</li><li><strong>Borrar / Backspace:</strong> borra el carácter justo antes del cursor.</li><li><strong>Flechas:</strong> mueven el cursor dentro de un texto sin usar el mouse.</li><li><strong>Shift (mayúsculas):</strong> mantenla presionada para escribir una letra en MAYÚSCULA o el símbolo de arriba de una tecla.</li></ul>","exercises":[{"id":"pc-03-1","type":"challenge","prompt":"Practica: haz clic derecho sobre el escritorio (donde no haya ningún icono) y observa qué opciones aparecen. No hace falta hacer clic en ninguna, solo mirar.","solution":""}],"resources":[],"quiz":{"question":"¿Para qué sirve el clic derecho del mouse?","options":["Para apagar la computadora","Para abrir un menú con opciones extra","Para escribir texto","No sirve para nada"],"correctIndex":1},"comments":[]},{"id":"pc-04","order":4,"type":"text","title":"Carpetas y archivos: cómo se organiza todo","description":"La misma lógica que un archivero físico, pero dentro de la pantalla.","content":"<h2>Archivo = un documento. Carpeta = donde lo guardas</h2><p>Un <strong>archivo</strong> es cualquier cosa que guardas: una foto, un documento de texto, una canción. Una <strong>carpeta</strong> es un contenedor donde metes archivos (y hasta otras carpetas adentro) para tenerlos organizados.</p><div class=\"example\">🧪 Es exactamente como un archivero de oficina: cada carpeta física guarda hojas (archivos) relacionadas entre sí — \"Recibos 2024\", \"Fotos de la familia\". La computadora usa la misma idea, solo que digital.</div><h2>Abrir, guardar y mover</h2><ul><li><strong>Abrir:</strong> doble clic sobre el archivo o la carpeta.</li><li><strong>Guardar:</strong> casi todo programa tiene un botón o menú \"Guardar\" — úsalo seguido para no perder tu trabajo si algo falla.</li><li><strong>Mover:</strong> arrastra el archivo con el mouse desde donde está hasta la carpeta donde lo quieres, y suelta.</li></ul><div class=\"tip\">💡 Cuando guardas algo por primera vez, la computadora te pregunta DÓNDE guardarlo y CÓMO se va a llamar — elige un nombre que te ayude a reconocerlo después (por ejemplo \"Carta para Juan\" en vez de \"documento1\").</div>","exercises":[{"id":"pc-04-1","type":"challenge","prompt":"Busca en tu computadora una carpeta que ya exista (Documentos, Descargas, Imágenes) y ábrela. ¿Qué archivos ves adentro?","solution":""}],"resources":[],"quiz":{"question":"¿Cuál es la diferencia entre un archivo y una carpeta?","options":["Son exactamente lo mismo","El archivo es el contenido (una foto, un documento); la carpeta lo organiza y guarda","La carpeta solo sirve para fotos","El archivo siempre está vacío"],"correctIndex":1},"comments":[]},{"id":"pc-05","order":5,"type":"text","title":"Internet y el navegador","description":"Qué es internet en palabras simples, y cómo moverte en él.","content":"<h2>¿Qué es internet, en palabras simples?</h2><p>Internet es una <strong>red gigante de computadoras conectadas entre sí</strong> alrededor del mundo, que se pueden mandar información unas a otras. Cuando \"entras a internet\", tu computadora se conecta a esa red — normalmente por wifi (sin cables) o un cable directo.</p><h2>El navegador: tu ventana hacia internet</h2><p>Un <strong>navegador</strong> (Chrome, Safari, Edge, Firefox) es el programa que usas para VER páginas de internet. Sin un navegador abierto, no puedes ver páginas web — es literalmente tu ventana hacia todo lo demás.</p><ul><li><strong>Barra de direcciones:</strong> arriba de la ventana — ahí escribes la dirección de una página (como <code>google.com</code>) o lo que quieras buscar.</li><li><strong>Buscador:</strong> escribe lo que quieras encontrar (por ejemplo \"receta de pastel de chocolate\") y presiona Enter — te muestra páginas relacionadas.</li><li><strong>Enlace (link):</strong> texto o imagen, normalmente subrayada o de otro color, que al hacer clic te lleva a otra página.</li><li><strong>Pestaña:</strong> cada pestaña abierta arriba del navegador es como una página distinta abierta al mismo tiempo — puedes tener varias sin cerrar las anteriores.</li></ul><div class=\"tip\">💡 No necesitas saber la dirección exacta de una página para encontrarla — escribe lo que buscas en palabras normales en la barra de direcciones o en Google, y la mayoría de las veces encontrarás lo que necesitas.</div>","exercises":[{"id":"pc-05-1","type":"challenge","prompt":"Abre tu navegador, escribe algo que quieras aprender en el buscador, y encuentra una página con la respuesta. ¿Qué buscaste?","solution":""}],"resources":[],"quiz":{"question":"¿Qué es un navegador?","options":["Una parte física de la computadora","El programa que usas para ver páginas de internet","Un tipo de virus","La misma cosa que un archivo"],"correctIndex":1},"comments":[]},{"id":"pc-06","order":6,"type":"text","title":"Contraseñas y cuidarte en línea","description":"Lo básico para estar segura/o en internet, sin volverte paranoico.","content":"<h2>Una buena contraseña</h2><p>Una contraseña fuerte es <strong>larga</strong> (mejor 12+ caracteres) y mezcla letras, números y algún símbolo — evita cosas obvias como tu nombre o \"123456\". Piensa en una frase que recuerdes fácil y combínala con números: por ejemplo \"MiPerroCorre2024!\".</p><div class=\"warn\">⚠️ Nunca compartas tus contraseñas con nadie que te las pida por mensaje, llamada o correo — ni bancos ni empresas reales las piden así. Si alguien te las pide de esa forma, es casi siempre un engaño.</div><h2>Reconocer enlaces sospechosos</h2><p>Antes de hacer clic en un enlace de un correo o mensaje desconocido, pregúntate: ¿esperaba yo este mensaje? ¿Me urge de forma rara (\"¡tu cuenta será cerrada en 1 hora!\")? Esa urgencia falsa es una señal clásica de engaño (phishing).</p><div class=\"tip\">💡 Si algo se ve raro, no tienes que decidir sola/o — pregúntale a alguien de confianza o a tu mascota IA antes de hacer clic. No hay ninguna prisa real casi nunca.</div><h2>Un hábito simple que ayuda mucho</h2><p>Usa una contraseña <strong>distinta</strong> para tu correo y para cosas importantes (banco) que para páginas menos importantes — así, si una se filtra, no arrastra a todas las demás.</p>","exercises":[{"id":"pc-06-1","type":"challenge","prompt":"Piensa en un correo o mensaje sospechoso que hayas recibido alguna vez. ¿Qué señales de alerta tenía? Cuéntaselo a tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué es una señal clásica de un mensaje engañoso (phishing)?","options":["Que venga de un amigo conocido","Urgencia falsa, como amenazar con cerrar tu cuenta pronto","Que tenga imágenes","Que sea muy corto"],"correctIndex":1},"comments":[]},{"id":"pc-07","order":7,"type":"text","title":"Palabras que vas a escuchar seguido","description":"Un glosario rápido de términos comunes, explicados sin tecnicismos.","content":"<h2>Glosario básico</h2><div class=\"example\">🧪 <strong>USB:</strong> un tipo de conector/puerto pequeño y plano donde enchufas cosas como una memoria, un mouse o un cargador.</div><div class=\"example\">🧪 <strong>Wifi:</strong> la forma de conectarte a internet sin cables, usando ondas en el aire — como una radio, pero para internet.</div><div class=\"example\">🧪 <strong>App (aplicación):</strong> un programa, normalmente en un celular o tablet, que hace una tarea específica (mandar mensajes, ver fotos, jugar).</div><div class=\"example\">🧪 <strong>La nube:</strong> guardar tus archivos en computadoras de internet en vez de solo en tu aparato — así puedes verlos desde otro celular o computadora, y no se pierden si tu aparato se rompe.</div><div class=\"example\">🧪 <strong>Actualizar:</strong> instalar una versión más nueva de un programa, normalmente con mejoras y arreglos.</div><div class=\"example\">🧪 <strong>Descargar:</strong> traer un archivo desde internet hacia tu computadora, para guardarlo ahí.</div><div class=\"tip\">💡 No hace falta memorizar esta lista de una sola vez — vuelve a esta clase cada vez que escuches una de estas palabras y no recuerdes bien qué significa. Para eso está.</div><h2>Ya diste el primer paso</h2><p>Si llegaste hasta aquí, ya sabes moverte por una computadora, abrir y guardar archivos, navegar internet con seguridad básica, y reconoces las palabras que más vas a escuchar. Eso es exactamente donde tenías que estar para empezar a explorar el resto de la Academia.</p>","exercises":[],"resources":[],"quiz":null,"comments":[]}]'::jsonb)
on conflict (id) do update set
  title = excluded.title, description = excluded.description, ai_instructions = excluded.ai_instructions,
  icon = excluded.icon, color = excluded.color, category = excluded.category, subcategory = excluded.subcategory,
  difficulty = excluded.difficulty, locked = excluded.locked, modules = excluded.modules, updated_at = now();
